// resourceIDFieldOverrides projects per-resource IDField (set by the profiler
// from x-resource-id or response-schema fallback) into a runtime lookup map.
// UpsertBatch consults this first so the templated path wins over the
// generic fallback list. Empty when no resource declared an override; the
// runtime fallback list still applies.
//
// Includes both flat resources and dependent (parent-child) resources so a
// child path-item annotated with x-resource-id resolves the same as a flat
// path-item.
var resourceIDFieldOverrides = map[string]string{
	"billing":                             "id",
	"billing-agreements":                  "id",
	"billing-invoices":                    "id",
	"billing-products":                    "id",
	"checklist":                           "id",
	"contacts":                            "id",
	"document-templates":                  "id",
	"itam":                                "id",
	"knowledgebase":                       "id",
	"knowledgebase-global-articles":       "id",
	"knowledgebase-organization-articles": "id",
	"organization":                        "organizationId",
	"organization-checklists":             "id",
	"queries-backup-usage":                "id",
	"related-items":                       "id",
	"software-license":                    "id",
	"tag":                                 "id",
	"ticketing-app-user-contact":          "id",
	"user":                                "id",
	"user-end-users":                      "id",
	"user-technicians":                    "id",
	"vulnerability":                       "id",
}

// genericIDFieldFallbacks is the runtime safety net for resources that did
// NOT receive a templated IDField. API-specific names belong in spec
// annotations (x-resource-id), not this list. Order matters: vendor
// identifier names (gid, sid, uid, uuid, guid) take precedence over `name`
// so APIs like Asana (gid) and Twilio (sid) don't fall through to a display
// field and upsert on names — see #1394.
var genericIDFieldFallbacks = []string{"id", "ID", "gid", "sid", "uid", "uuid", "guid", "name", "slug", "key", "code"}

// ExtractResourceID resolves the primary key UpsertBatch would use for a
// resource item. Callers that need to gate best-effort writes can use this to
// avoid passing non-entity envelopes into the batch path.
func ExtractResourceID(resourceType string, obj map[string]any) string {
	if override, ok := resourceIDFieldOverrides[resourceType]; ok && override != "" {
		if v := lookupFieldValue(obj, override); v != nil {
			s := ResourceIDString(v)
			if s != "" && s != "<nil>" {
				return s
			}
		}
	}
	for _, key := range genericIDFieldFallbacks {
		if v := lookupFieldValue(obj, key); v != nil {
			s := ResourceIDString(v)
			if s != "" && s != "<nil>" {
				return s
			}
		}
	}
	return ""
}

// UpsertBatch inserts or replaces multiple records in a single transaction
// and returns (stored, extractFailures, err). stored counts rows landed in
// the generic resources table; extractFailures counts items that survived
// JSON unmarshal but had no extractable primary key (templated IDField AND
// generic fallback both missed). callers (sync.go.tmpl) compare these
// against len(items) to emit the per-item primary_key_unresolved warning
// and the F4b stored_count_zero_after_extraction probe.
//
// For resource types that have a domain-specific typed table, the per-item
// generic insert is followed by a dispatch to the matching upsert<Pascal>Tx
// inside the same transaction. Without that dispatch, paginated syncs would
// only populate the generic resources table — typed tables (and indexed
// columns like parent_id added by dependent-resource sync) would stay empty.
//
// Each typed-table dispatch runs inside a per-item SAVEPOINT so a constraint
// failure in the typed insert (e.g. NOT NULL parent FK when the generator
// didn't populate the parent path placeholder) rolls back only that typed
// upsert. The generic resources row inserted just above it survives the
// rollback, so successful API fetches never strand in memory because one
// downstream typed table is misconfigured. Failures are surfaced via a
// trailing stderr warning rather than aborting the batch.
func (s *Store) UpsertBatch(resourceType string, items []json.RawMessage) (int, int, error) {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return 0, 0, fmt.Errorf("starting batch transaction: %w", err)
	}
	defer tx.Rollback()

	var stored, skippedCount, extractFailures, typedFailures int
	for i, item := range items {
		obj, err := DecodeJSONObject(item)
		if err != nil {
			skippedCount++
			continue
		}
		// Templated IDField wins; generic fallback list runs second when
		// the override is empty OR the override field is absent on this
		// particular item (response shape mismatches happen even when the
		// spec declares x-resource-id).
		id := ExtractResourceID(resourceType, obj)
		if id == "" {
			skippedCount++
			extractFailures++
			continue
		}

		if err := s.upsertGenericResourceTx(tx, resourceType, id, item); err != nil {
			// Return the running stored count rather than zero so callers
			// inspecting partial progress on failure see what already
			// landed in earlier loop iterations.
			return stored, extractFailures, fmt.Errorf("upserting %s/%s: %w", resourceType, id, err)
		}
		stored++

		savepoint := fmt.Sprintf("pp_typed_%d", i)
		if _, err := tx.Exec("SAVEPOINT " + savepoint); err != nil {
			return stored, extractFailures, fmt.Errorf("savepoint begin for %s/%s: %w", resourceType, id, err)
		}

		var typedErr error
		switch resourceType {
		case "reset":
			typedErr = s.upsertResetTx(tx, id, obj, item)
		case "attachments":
			typedErr = s.upsertAttachmentsTx(tx, id, obj, item)
		case "backup":
			typedErr = s.upsertBackupTx(tx, id, obj, item)
		case "billing":
			typedErr = s.upsertBillingTx(tx, id, obj, item)
		case "checklist":
			typedErr = s.upsertChecklistTx(tx, id, obj, item)
		case "contact":
			typedErr = s.upsertContactTx(tx, id, obj, item)
		case "contacts":
			typedErr = s.upsertContactsTx(tx, id, obj, item)
		case "custom-fields":
			typedErr = s.upsertCustomFieldsTx(tx, id, obj, item)
		case "device":
			typedErr = s.upsertDeviceTx(tx, id, obj, item)
		case "device_activities":
			typedErr = s.upsertDeviceActivitiesTx(tx, id, obj, item)
		case "device_alerts":
			typedErr = s.upsertDeviceAlertsTx(tx, id, obj, item)
		case "device_custom_fields":
			typedErr = s.upsertDeviceCustomFieldsTx(tx, id, obj, item)
		case "dashboard_url":
			typedErr = s.upsertDashboardUrlTx(tx, id, obj, item)
		case "decommission":
			typedErr = s.upsertDecommissionTx(tx, id, obj, item)
		case "disks":
			typedErr = s.upsertDisksTx(tx, id, obj, item)
		case "jobs":
			typedErr = s.upsertJobsTx(tx, id, obj, item)
		case "last_logged_on_user":
			typedErr = s.upsertLastLoggedOnUserTx(tx, id, obj, item)
		case "maintenance":
			typedErr = s.upsertMaintenanceTx(tx, id, obj, item)
		case "network_interfaces":
			typedErr = s.upsertNetworkInterfacesTx(tx, id, obj, item)
		case "os_patch_installs":
			typedErr = s.upsertOsPatchInstallsTx(tx, id, obj, item)
		case "os_patches":
			typedErr = s.upsertOsPatchesTx(tx, id, obj, item)
		case "owner":
			typedErr = s.upsertOwnerTx(tx, id, obj, item)
		case "patch":
			typedErr = s.upsertPatchTx(tx, id, obj, item)
		case "policy":
			typedErr = s.upsertPolicyTx(tx, id, obj, item)
		case "processors":
			typedErr = s.upsertProcessorsTx(tx, id, obj, item)
		case "reboot":
			typedErr = s.upsertRebootTx(tx, id, obj, item)
		case "script":
			typedErr = s.upsertScriptTx(tx, id, obj, item)
		case "scripting":
			typedErr = s.upsertScriptingTx(tx, id, obj, item)
		case "software":
			typedErr = s.upsertSoftwareTx(tx, id, obj, item)
		case "software_patch_installs":
			typedErr = s.upsertSoftwarePatchInstallsTx(tx, id, obj, item)
		case "software_patches":
			typedErr = s.upsertSoftwarePatchesTx(tx, id, obj, item)
		case "volumes":
			typedErr = s.upsertVolumesTx(tx, id, obj, item)
		case "windows_service":
			typedErr = s.upsertWindowsServiceTx(tx, id, obj, item)
		case "windows_services":
			typedErr = s.upsertWindowsServicesTx(tx, id, obj, item)
		case "document-templates":
			typedErr = s.upsertDocumentTemplatesTx(tx, id, obj, item)
		case "archive":
			typedErr = s.upsertArchiveTx(tx, id, obj, item)
		case "restore":
			typedErr = s.upsertRestoreTx(tx, id, obj, item)
		case "device_ids":
			typedErr = s.upsertDeviceIdsTx(tx, id, obj, item)
		case "itam":
			typedErr = s.upsertItamTx(tx, id, obj, item)
		case "knowledgebase":
			typedErr = s.upsertKnowledgebaseTx(tx, id, obj, item)
		case "noderole":
			typedErr = s.upsertNoderoleTx(tx, id, obj, item)
		case "organization":
			typedErr = s.upsertOrganizationTx(tx, id, obj, item)
		case "checklists_from_templates":
			typedErr = s.upsertChecklistsFromTemplatesTx(tx, id, obj, item)
		case "organization_custom_fields":
			typedErr = s.upsertOrganizationCustomFieldsTx(tx, id, obj, item)
		case "organization_devices":
			typedErr = s.upsertOrganizationDevicesTx(tx, id, obj, item)
		case "document":
			typedErr = s.upsertDocumentTx(tx, id, obj, item)
		case "documents":
			typedErr = s.upsertDocumentsTx(tx, id, obj, item)
		case "end_users":
			typedErr = s.upsertEndUsersTx(tx, id, obj, item)
		case "location":
			typedErr = s.upsertLocationTx(tx, id, obj, item)
		case "organization_locations":
			typedErr = s.upsertOrganizationLocationsTx(tx, id, obj, item)
		case "organization_policies":
			typedErr = s.upsertOrganizationPoliciesTx(tx, id, obj, item)
		case "template":
			typedErr = s.upsertTemplateTx(tx, id, obj, item)
		case "condition":
			typedErr = s.upsertConditionTx(tx, id, obj, item)
		case "queries":
			typedErr = s.upsertQueriesTx(tx, id, obj, item)
		case "related-items":
			typedErr = s.upsertRelatedItemsTx(tx, id, obj, item)
		case "attachment":
			typedErr = s.upsertAttachmentTx(tx, id, obj, item)
		case "software-license":
			typedErr = s.upsertSoftwareLicenseTx(tx, id, obj, item)
		case "assignments":
			typedErr = s.upsertAssignmentsTx(tx, id, obj, item)
		case "tab":
			typedErr = s.upsertTabTx(tx, id, obj, item)
		case "end_user":
			typedErr = s.upsertEndUserTx(tx, id, obj, item)
		case "tab_organization":
			typedErr = s.upsertTabOrganizationTx(tx, id, obj, item)
		case "role":
			typedErr = s.upsertRoleTx(tx, id, obj, item)
		case "tag":
			typedErr = s.upsertTagTx(tx, id, obj, item)
		case "ticketing":
			typedErr = s.upsertTicketingTx(tx, id, obj, item)
		case "user":
			typedErr = s.upsertUserTx(tx, id, obj, item)
		case "vulnerability":
			typedErr = s.upsertVulnerabilityTx(tx, id, obj, item)
		}

		if typedErr != nil {
			if _, rbErr := tx.Exec("ROLLBACK TO SAVEPOINT " + savepoint); rbErr != nil {
				return stored, extractFailures, fmt.Errorf("rollback to savepoint for %s/%s (typed err: %v): %w", resourceType, id, typedErr, rbErr)
			}
			if _, relErr := tx.Exec("RELEASE SAVEPOINT " + savepoint); relErr != nil {
				return stored, extractFailures, fmt.Errorf("release savepoint after rollback for %s/%s: %w", resourceType, id, relErr)
			}
			typedFailures++
			continue
		}
		if _, err := tx.Exec("RELEASE SAVEPOINT " + savepoint); err != nil {
			return stored, extractFailures, fmt.Errorf("release savepoint for %s/%s: %w", resourceType, id, err)
		}
	}

	// Warn when most items in a batch lack an extractable ID — this likely
	// means the API uses a primary key field we don't recognize yet.
	if skippedCount > 0 && len(items) > 0 && skippedCount*2 > len(items) {
		fmt.Fprintf(os.Stderr, "warning: %d/%d %s items returned but not cached locally (no extractable ID field; offline lookup against these rows will be incomplete; live queries unaffected)\n", skippedCount, len(items), resourceType)
	}
	// Surface typed-table failures without aborting the batch. Generic rows
	// already committed; only the typed projection failed.
	if typedFailures > 0 {
		fmt.Fprintf(os.Stderr, "warning: %d/%d %s items: typed-table upsert failed; generic resources rows preserved\n", typedFailures, len(items), resourceType)
	}

	if err := tx.Commit(); err != nil {
		return 0, extractFailures, err
	}
	return stored, extractFailures, nil
}

// SearchBilling searches the billing_fts index with optional filters.
func (s *Store) SearchBilling(query string, limit int) ([]json.RawMessage, error) {
	if limit <= 0 {
		limit = 50
	}
	rows, err := s.db.Query(
		`SELECT t.data FROM "billing" t
		 JOIN "billing_fts" ON "billing_fts".rowid = t.rowid
		 WHERE "billing_fts" MATCH ?
		 ORDER BY rank LIMIT ?`,
		query, limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var results []json.RawMessage
	for rows.Next() {
		var data string
		if err := rows.Scan(&data); err != nil {
			return nil, err
		}
		results = append(results, json.RawMessage(data))
	}
	return results, rows.Err()
}

